WITH s AS (SELECT r.profile_date, r.account_key, r.daily_rank, r.total_amount_usd, r.ach_points, r.cross_border_points, r.fan_out_points, r.fan_in_points, r.amount_band_points, r.pass_through_points, r.activity_spike_points, COALESCE(l.account_day_is_laundering, 0) AS y
FROM risk_rankings r LEFT JOIN account_labels l ON l.account_key = r.account_key AND l.profile_date = r.profile_date WHERE r.profile_date IN ({date_list})),
t AS (SELECT s.*, s.ach_points + s.cross_border_points + s.fan_out_points + s.fan_in_points + s.amount_band_points + s.pass_through_points + s.activity_spike_points AS full_pts FROM s),
ranked AS (SELECT y, daily_rank, ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(full_pts - ach_points, 4) DESC, total_amount_usd DESC, account_key) AS wo_ach_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(ach_points, 4) DESC, total_amount_usd DESC, account_key) AS only_ach_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(full_pts - cross_border_points, 4) DESC, total_amount_usd DESC, account_key) AS wo_cross_border_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(cross_border_points, 4) DESC, total_amount_usd DESC, account_key) AS only_cross_border_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(full_pts - fan_out_points, 4) DESC, total_amount_usd DESC, account_key) AS wo_fan_out_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(fan_out_points, 4) DESC, total_amount_usd DESC, account_key) AS only_fan_out_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(full_pts - fan_in_points, 4) DESC, total_amount_usd DESC, account_key) AS wo_fan_in_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(fan_in_points, 4) DESC, total_amount_usd DESC, account_key) AS only_fan_in_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(full_pts - amount_band_points, 4) DESC, total_amount_usd DESC, account_key) AS wo_amount_band_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(amount_band_points, 4) DESC, total_amount_usd DESC, account_key) AS only_amount_band_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(full_pts - pass_through_points, 4) DESC, total_amount_usd DESC, account_key) AS wo_pass_through_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(pass_through_points, 4) DESC, total_amount_usd DESC, account_key) AS only_pass_through_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(full_pts - activity_spike_points, 4) DESC, total_amount_usd DESC, account_key) AS wo_activity_spike_points,
ROW_NUMBER() OVER (PARTITION BY profile_date ORDER BY ROUND(activity_spike_points, 4) DESC, total_amount_usd DESC, account_key) AS only_activity_spike_points FROM t)
SELECT SUM(CASE WHEN daily_rank <= {top_n} THEN y ELSE 0 END) AS caught_all, SUM(CASE WHEN wo_ach_points <= {top_n} THEN y ELSE 0 END) AS wo_ach_points,
SUM(CASE WHEN only_ach_points <= {top_n} THEN y ELSE 0 END) AS only_ach_points,
SUM(CASE WHEN wo_cross_border_points <= {top_n} THEN y ELSE 0 END) AS wo_cross_border_points,
SUM(CASE WHEN only_cross_border_points <= {top_n} THEN y ELSE 0 END) AS only_cross_border_points,
SUM(CASE WHEN wo_fan_out_points <= {top_n} THEN y ELSE 0 END) AS wo_fan_out_points,
SUM(CASE WHEN only_fan_out_points <= {top_n} THEN y ELSE 0 END) AS only_fan_out_points,
SUM(CASE WHEN wo_fan_in_points <= {top_n} THEN y ELSE 0 END) AS wo_fan_in_points,
SUM(CASE WHEN only_fan_in_points <= {top_n} THEN y ELSE 0 END) AS only_fan_in_points,
SUM(CASE WHEN wo_amount_band_points <= {top_n} THEN y ELSE 0 END) AS wo_amount_band_points,
SUM(CASE WHEN only_amount_band_points <= {top_n} THEN y ELSE 0 END) AS only_amount_band_points,
SUM(CASE WHEN wo_pass_through_points <= {top_n} THEN y ELSE 0 END) AS wo_pass_through_points,
SUM(CASE WHEN only_pass_through_points <= {top_n} THEN y ELSE 0 END) AS only_pass_through_points,
SUM(CASE WHEN wo_activity_spike_points <= {top_n} THEN y ELSE 0 END) AS wo_activity_spike_points,
SUM(CASE WHEN only_activity_spike_points <= {top_n} THEN y ELSE 0 END) AS only_activity_spike_points FROM ranked
